/// Spec-style helper: counts eligible participants in the whole slice.
/// (In the original spec it takes Seq<int>; here we use a Rust slice.)
fn count_eligible(participations: &[u8], k: u8) -> usize {
    let k16 = k as u16;
    participations
        .iter()
        .filter(|&&a| (a as u16) + k16 <= 5)
        .count()
}

/// Required function: consider only the first `n` elements (or fewer if not present),
/// count eligible participants, and return max number of disjoint teams of 3.
fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let take_n = n as usize;
    let eligible = count_eligible(&participations[..participations.len().min(take_n)], k);
    (eligible / 3) as u8
}

